-- Fleet. Seat maps come from the same generator the admin UI uses (ops_generate_seat_map).
DO $$
DECLARE
  a320 jsonb := '{"cabins":[{"class":"Business","fromRow":1,"toRow":2,"letters":"AC DF"},
                            {"class":"Economy","fromRow":3,"toRow":31,"letters":"ABC DEF"}],"exitRows":[12,13]}';
  atr  jsonb := '{"cabins":[{"class":"Economy","fromRow":1,"toRow":18,"letters":"AC DF"}],"exitRows":[1]}';
  b789 jsonb := '{"cabins":[{"class":"First","fromRow":1,"toRow":2,"letters":"A DG K"},
                            {"class":"Business","fromRow":3,"toRow":8,"letters":"AC DG HK"},
                            {"class":"Economy","fromRow":10,"toRow":40,"letters":"ABC DEF HJK"}],"exitRows":[10,25]}';
  a359 jsonb := '{"cabins":[{"class":"Business","fromRow":1,"toRow":8,"letters":"A DG K"},
                            {"class":"Economy","fromRow":10,"toRow":38,"letters":"ABC DEF HJK"}],"exitRows":[10,24]}';
  r text; i integer;
BEGIN
  FOR i IN 0 .. 25 LOOP   -- VT-SKA .. VT-SKZ
    PERFORM ops_add_aircraft('VT-SK' || chr(65 + i), 'A320neo', 'Airbus', 'A20N', 2016 + i % 8, a320);
  END LOOP;
  FOREACH r IN ARRAY ARRAY['VT-SRA','VT-SRB','VT-SRC','VT-SRD'] LOOP
    PERFORM ops_add_aircraft(r, 'ATR 72-600', 'ATR', 'AT76', 2018, atr);
  END LOOP;
  FOREACH r IN ARRAY ARRAY['VT-SWA','VT-SWB','VT-SWC','VT-SWD','VT-SWE','VT-SWF','VT-SWG','VT-SWH'] LOOP
    PERFORM ops_add_aircraft(r, '787-9 Dreamliner', 'Boeing', 'B789', 2019, b789);
  END LOOP;
  FOREACH r IN ARRAY ARRAY['VT-SXA','VT-SXB','VT-SXC'] LOOP
    PERFORM ops_add_aircraft(r, 'A350-900', 'Airbus', 'A359', 2021, a359);
  END LOOP;
END $$;
